const fs = require("fs"), path = require("path"), os = require("os"), zlib = require("zlib");
const TZ = 8 * 3600 * 1000;
const dayStart = new Date("2026-11-09T00:00:00+08:00").getTime();
const dayEnd = dayStart + 864e5;
const base = path.join(os.homedir(), ".dsh", "sessions");
const files = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name)) {
      const st = fs.statSync(fp);
      if (st.mtimeMs >= dayStart && st.mtimeMs < dayEnd) files.push(fp);
    }
  }
})(base);
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString("utf8"); } catch { return buf.toString("utf8"); } }
  let o = "";
  for (let k = 0; k < idx.length; k++) {
    const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length;
    try { o += zlib.zstdDecompressSync(buf.subarray(s, e)).toString("utf8"); } catch {}
  }
  return o;
}
function load(fp) {
  return dec(fs.readFileSync(fp)).split("\n").filter(Boolean).flatMap(l => { try { return [JSON.parse(l)]; } catch { return []; } });
}
function tsOf(e) {
  const v = e.ts || e.timestamp || e.time || e.createdAt || (e.data && e.data.ts);
  if (v == null) return null;
  const n = typeof v === "number" ? v : Date.parse(v);
  return Number.isFinite(n) ? n : null;
}
function bjHour(n) { return n == null ? "--" : new Date(n + TZ).toISOString().slice(11, 13); }
const cross = {}, samples = [], prov = [], perHour = {};
for (const fp of files) {
  const sid = path.basename(path.dirname(fp)).replace(/^session-/, "").slice(0, 8);
  const ev = load(fp);
  const nameByCall = {};
  for (const c of ev) if (c.type === "tool/call") nameByCall[c.data.callId] = c.data.name;
  for (const tr of ev) {
    const err = tr.data && tr.data.error;
    if (!err) continue;
    const code = String(err.code || err.name || "OTHER");
    const cid = tr.data.message && tr.data.message.toolCallId;
    const nm = (nameByCall[cid] || "?").replace(/[\s"'<>]+/g, "");
    const k = code + " | " + nm;
    cross[k] = (cross[k] || 0) + 1;
    const h = bjHour(tsOf(tr));
    perHour[h] = (perHour[h] || 0) + 1;
    samples.push({ sid, h, nm, code, msg: String(err.message || err.detail || "").replace(/\s+/g, " ").slice(0, 160) });
  }
  for (const e of ev) {
    if (!/llm\/(retry|error|failure)|provider/.test(e.type || "")) continue;
    const d = e.data || {}, f = d.failure || {};
    const code = String(f.code || d.code || "").toUpperCase();
    const msg = String(f.message || d.message || d.error || "");
    if (!code && !msg) continue;
    if (/EMPTY_RESPONSE/.test(code)) continue;
    prov.push({ sid, h: bjHour(tsOf(e)), provider: String(d.provider || f.provider || "?"), code, msg: msg.replace(/\s+/g, " ").slice(0, 160) });
  }
}
console.log("=== 错误码 x 工具 ===");
Object.entries(cross).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => console.log(String(v).padStart(3), k));
console.log("\n=== 失败按北京时间(小时) ===");
Object.entries(perHour).sort().forEach(([k, v]) => console.log(k + "时", v));
console.log("\n=== 工具失败样本(" + samples.length + ") ===");
samples.forEach(s => console.log(s.sid, s.h, s.nm.padEnd(16), s.code.padEnd(26), s.msg));
console.log("\n=== 供应商层(" + prov.length + ") ===");
prov.forEach(p => console.log(p.sid, p.h, p.provider, p.code, p.msg));
const led = path.join(os.homedir(), ".dsh", "reports", "agent-guard-ledger.jsonl");
if (fs.existsSync(led)) {
  const today = fs.readFileSync(led, "utf8").split("\n").filter(Boolean).flatMap(l => { try { return [JSON.parse(l)]; } catch { return []; } })
    .filter(x => { const t = Date.parse(x.ts); return t >= dayStart && t < dayEnd; });
  const gr = {};
  for (const x of today) { const k = x.kind + "/" + x.rule + "/" + (x.tool || "-"); gr[k] = (gr[k] || 0) + 1; }
  console.log("\n=== guard ledger 今日(" + today.length + " 条) ===");
  Object.entries(gr).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => console.log(String(v).padStart(3), k));
}

