import fs from "fs";
import path from "path";
import os from "os";
import zlib from "zlib";
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString("utf8"); } catch { return buf.toString("utf8"); } }
  let o = "";
  for (let k = 0; k < idx.length; k++) {
    const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length;
    try { o += zlib.zstdDecompressSync(buf.subarray(s, e)).toString("utf8"); } catch {}
  }
  return o;
}
function load(fp) {
  return dec(fs.readFileSync(fp)).split("\n").filter(Boolean).flatMap(l => { try { return [JSON.parse(l)]; } catch { return []; } });
}
const base = path.join(os.homedir(), ".dsh", "sessions");
const target = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name) && path.basename(path.dirname(fp)).includes("904a727e")) target.push(fp);
  }
})(base);
console.log("匹配会话文件: " + target.length);
for (const fp of target) {
  const ev = load(fp);
  console.log("\n=== 会话头（前 6 事件）===");
  ev.slice(0, 6).forEach(e => console.log(e.type, JSON.stringify(e.data || {}).slice(0, 180)));
  const meta = ev.filter(e => /model|provider/i.test(JSON.stringify(e).slice(0, 400))).slice(0, 3);
  console.log("\n=== 模型/provider 线索 ===");
  meta.forEach(e => console.log(e.type, JSON.stringify(e.data || {}).slice(0, 240)));
  const calls = {};
  for (const c of ev) if (c.type === "tool/call") calls[c.data.callId] = { name: c.data.name, args: c.data.arguments || c.data.args || {} };
  console.log("\n=== 失败调用的参数与错误体 ===");
  let n = 0;
  for (const tr of ev) {
    const err = tr.data && tr.data.error;
    if (!err) continue;
    n++;
    const cid = tr.data.message && tr.data.message.toolCallId;
    const c = calls[cid] || { name: "?", args: {} };
    console.log("#" + n, c.name, "code=" + String(err.code || err.name || "OTHER"));
    console.log("   args:", JSON.stringify(c.args).slice(0, 320));
    console.log("   err :", JSON.stringify(err).slice(0, 360));
  }
}

